import Foundation

/// `Sprites/manifest.json`: which strip, how many frames and what speed each state uses.
/// Generated by `scripts/gen_sprites.py`; swapping the PNGs and this file swaps the character.
public struct SpriteManifest: Codable, Equatable, Sendable {
    public struct Entry: Codable, Equatable, Sendable {
        public var frames: Int
        public var fps: Double
        public var size16: String
        public var size32: String?
        public var frames32: Int?

        public init(frames: Int, fps: Double, size16: String, size32: String? = nil, frames32: Int? = nil) {
            self.frames = frames
            self.fps = fps
            self.size16 = size16
            self.size32 = size32
            self.frames32 = frames32
        }
    }

    public var states: [String: Entry]
    public var idle: [String]

    public init(json: Data) throws {
        self = try JSONDecoder().decode(SpriteManifest.self, from: json)
    }

    public func entry(for state: CompanionState) -> Entry? {
        states[state.spriteName]
    }
}
